# owner: platform
import unittest
from tests.support import data_file
from hourglass.timesheet import timesheet_rows
from hourglass.schedule import load_schedule
from hourglass.models import Shift, Span

def make_shift(worker, minutes):
    """A Monday shift from nine o'clock, lasting the given minutes."""
    return Shift(worker, "mon", Span(540, 540 + minutes))

class TimesheetRowTests(unittest.TestCase):
    def test_busiest_first_with_counts_and_hours(self):
        shifts = load_schedule(data_file("schedule.csv"))
        self.assertEqual(
            timesheet_rows(shifts),
            [
                "Brisa: 3 shifts, 9.0 hours",
                "Quill: 2 shifts, 7.5 hours",
                "Odell: 2 shifts, 6.5 hours",
            ],
        )

    def test_hours_to_one_decimal_place(self):
        shifts = [make_shift("Brisa", 100)]
        self.assertEqual(timesheet_rows(shifts), ["Brisa: 1 shift, 1.7 hours"])

    def test_ties_sorted_by_name(self):
        shifts = [make_shift("Quill", 60), make_shift("Brisa", 60)]
        self.assertEqual(
            timesheet_rows(shifts),
            ["Brisa: 1 shift, 1.0 hours", "Quill: 1 shift, 1.0 hours"],
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        shifts = [make_shift("Brisa", 60), make_shift("  ", 60)]
        with self.assertRaises(ValueError):
            timesheet_rows(shifts)
